import sys, json
sys.path.insert(0, '/workspace')
from pydantic import BaseModel, ConfigDict, Field, ValidationError, AliasChoices, AliasPath
from typing import Annotated
def errors(fn):
    try:
        fn()
    except ValidationError as exc:
        return [[list(e['loc']), e['type']] for e in exc.errors()]
    except Exception as exc:
        return type(exc).__name__
    return []
class Choice(BaseModel):
    model_config=ConfigDict(validate_by_name=True, extra='forbid')
    value: int = Field(validation_alias=AliasChoices('legacy', AliasPath('payload', 0)), serialization_alias='out')
both={'legacy':'1','payload':['2'],'value':'3'}
rows={
 'both':errors(lambda:Choice.model_validate(both)),
 'ignore':Choice.model_validate(both, extra='ignore').model_dump(),
 'path':Choice.model_validate({'payload':['2']}).model_dump(),
 'name':Choice.model_validate({'value':'3'}).model_dump(),
 'empty_path_with_name':Choice.model_validate({'payload':[],'value':'3'}, extra='ignore').model_dump(),
 'invalid_first':errors(lambda:Choice.model_validate({'legacy':'bad','payload':['2']}, extra='ignore')),
 'name_only_override':Choice.model_validate(both, by_alias=False, by_name=True, extra='ignore').model_dump(),
 'serialization':Choice.model_validate({'legacy':'1'}).model_dump(by_alias=True),
 'serialization_not_input':errors(lambda:Choice.model_validate({'out':'1'})),
 'disabled':errors(lambda:Choice.model_validate({'value':1}, by_alias=False)),
}
print(json.dumps(rows, sort_keys=True))
